using public.curriculum_subjects cs, public.curriculum_versions cv, public.academic_periods ap, public.source_documents sd
where cs.curriculum_version_id = cv.id
  and ap.subject_id = cs.id
  and sd.source_url = 'https://depedph-my.sharepoint.com/personal/ouct_deped_gov_ph/_layouts/15/onedrive.aspx?id=%2Fpersonal%2Fouct_deped_gov_ph%2FDocuments%2FMATATAG%20Curriculum%20Guides%2FFINAL%20MATATAG%20Makabansa%20CG%202023%20Grades%201-3.pdf&parent=%2Fpersonal%2Fouct_deped_gov_ph%2FDocuments%2FMATATAG%20Curriculum%20Guides'
  and cv.code = 'REVISED-K10-MATATAG'
  and cs.grade_level = 'Grade 1'
  and cs.name = 'Makabansa'
  and cc.subject_id = cs.id
  and cc.academic_period_id = ap.id
  and cc.source_document_id = sd.id
  and not ((ap.sequence = 1 and cc.sort_order in (1, 2, 3)) or (ap.sequence = 2 and cc.sort_order in (1, 2, 3)) or (ap.sequence = 3 and cc.sort_order in (1, 2, 3, 4)) or (ap.sequence = 4 and cc.sort_order in (1, 2, 3)));

