  and cs.grade_level = 'Grade 10'
  and cs.name = 'Araling Panlipunan'
  and cc.subject_id = cs.id
  and cc.academic_period_id = ap.id
  and cc.source_document_id = sd.id
  and not ((ap.sequence = 1 and cc.sort_order in (1, 2, 3, 4, 5)) or (ap.sequence = 2 and cc.sort_order in (1, 2, 3)) or (ap.sequence = 3 and cc.sort_order in (1, 2, 3, 4, 5, 6, 7)) or (ap.sequence = 4 and cc.sort_order in (1, 2, 3, 4, 5)));

