delete from public.curriculum_standards
where subject_id = (select cs.id from public.curriculum_subjects cs join public.curriculum_versions cv on cv.id = cs.curriculum_version_id where cv.code = 'REVISED-K10-MATATAG' and cs.grade_level = 'Grade 5' and cs.name = 'GMRC')
  and source_document_id = (select id from public.source_documents where source_url = 'https://depedph-my.sharepoint.com/personal/ouct_deped_gov_ph/_layouts/15/onedrive.aspx?id=%2Fpersonal%2Fouct_deped_gov_ph%2FDocuments%2FMATATAG%20Curriculum%20Guides%2FFINAL%20MATATAG%20GMRC%20and%20VE%20CG%202023%20Grades%201-10.pdf&parent=%2Fpersonal%2Fouct_deped_gov_ph%2FDocuments%2FMATATAG%20Curriculum%20Guides');

update public.curriculum_competencies cc
set domain_id = cd.id,
  competency_code = null,
  competency_text = 'Nakapagsasanay sa paggalang sa buhay sa pamamagitan ng pag-iingat at pagpapabuti ng sariling buhay a. Naiisa-isa ang mga kilos na nagpapahalaga sa sariling buhay b. Naipaliliwanag na ang mga kilos na nagpapahalaga sa sariling buhay ay paraan upang kilalanin ang sariling dignidad bilang tao at ang mga salik na nakaaapekto sa pagtataguyod nito c. Nailalapat ang mga kilos na nagpapahalaga sa sariling buhay bilang pagkilala sa kaniyang dignidad',
  source_page = 128,
  verification_status = 'verified',
  updated_at = timezone('utc', now())
from public.curriculum_subjects cs
join public.curriculum_versions cv on cv.id = cs.curriculum_version_id
join public.curriculum_domains cd on cd.subject_id = cs.id and cd.code = 'D01'
join public.academic_periods ap on ap.subject_id = cs.id and ap.sequence = 1
join public.source_documents sd on sd.source_url = 'https://depedph-my.sharepoint.com/personal/ouct_deped_gov_ph/_layouts/15/onedrive.aspx?id=%2Fpersonal%2Fouct_deped_gov_ph%2FDocuments%2FMATATAG%20Curriculum%20Guides%2FFINAL%20MATATAG%20GMRC%20and%20VE%20CG%202023%20Grades%201-10.pdf&parent=%2Fpersonal%2Fouct_deped_gov_ph%2FDocuments%2FMATATAG%20Curriculum%20Guides'
where cv.code = 'REVISED-K10-MATATAG'
  and cs.grade_level = 'Grade 5'
  and cs.name = 'GMRC'
  and cc.subject_id = cs.id
  and cc.academic_period_id = ap.id
  and cc.source_document_id = sd.id
  and cc.sort_order = 1;

insert into public.curriculum_competencies (subject_id, domain_id, academic_period_id, competency_code, competency_text, sort_order, source_document_id, source_page, verification_status)
select cs.id, cd.id, ap.id, null, 'Nakapagsasanay sa paggalang sa buhay sa pamamagitan ng pag-iingat at pagpapabuti ng sariling buhay a. Naiisa-isa ang mga kilos na nagpapahalaga sa sariling buhay b. Naipaliliwanag na ang mga kilos na nagpapahalaga sa sariling buhay ay paraan upang kilalanin ang sariling dignidad bilang tao at ang mga salik na nakaaapekto sa pagtataguyod nito c. Nailalapat ang mga kilos na nagpapahalaga sa sariling buhay bilang pagkilala sa kaniyang dignidad', 1, sd.id, 128, 'verified'
from public.curriculum_subjects cs
join public.curriculum_versions cv on cv.id = cs.curriculum_version_id
join public.curriculum_domains cd on cd.subject_id = cs.id and cd.code = 'D01'
join public.academic_periods ap on ap.subject_id = cs.id and ap.sequence = 1
join public.source_documents sd on sd.source_url = 'https://depedph-my.sharepoint.com/personal/ouct_deped_gov_ph/_layouts/15/onedrive.aspx?id=%2Fpersonal%2Fouct_deped_gov_ph%2FDocuments%2FMATATAG%20Curriculum%20Guides%2FFINAL%20MATATAG%20GMRC%20and%20VE%20CG%202023%20Grades%201-10.pdf&parent=%2Fpersonal%2Fouct_deped_gov_ph%2FDocuments%2FMATATAG%20Curriculum%20Guides'
where cv.code = 'REVISED-K10-MATATAG' and cs.grade_level = 'Grade 5' and cs.name = 'GMRC'
  and not exists (
    select 1 from public.curriculum_competencies cc
    where cc.subject_id = cs.id
      and cc.academic_period_id = ap.id
      and cc.source_document_id = sd.id
      and cc.sort_order = 1
  );

update public.curriculum_competencies cc
