  and cs.grade_level = 'Grade 5'
  and cs.name = 'MAPEH'
  and cc.subject_id = cs.id
  and cc.academic_period_id = ap.id
  and cc.source_document_id = sd.id
  and not ((ap.sequence = 1 and cc.sort_order in (1, 2, 3, 4)) or (ap.sequence = 2 and cc.sort_order in (1, 2, 3, 4)) or (ap.sequence = 3 and cc.sort_order in (1, 2, 3, 4)) or (ap.sequence = 4 and cc.sort_order in (1, 2, 3, 4)));

