update public.curriculum_competencies cc
set domain_id = cd.id,
  competency_code = null,
  competency_text = 'Nauunawaan ang tekstong ekspositori gamit ang mga kasanayang pang-akademik • Mga kasanayang pang-akademik (katulad ng pagtukoy sa paksa, layon at ideya, pagtatala ng mahahalagang impormasyon (detalye), mekaniks sa pagsulat (diksyon, estilo at paggamit ng transisyonal at kohesiyong gramatikal), paggamit ng angkop na mga salita sa pagbuo ng talata at pagpapahayag ng mga ideya) • Mga tekstong ekspositori (katulad ng memoirs, journals, personal na sanaysay, kasaysayan, heograpiya, aklat ukol sa mga hayop at halaman, tekstong pang-instruksyon, siyentipiko at medikal na teksto at ulat, legal na dokumento, impormasyonal na brochure, menu, resipe, listahan ng mga pamimili, at deskripsyon ng nilalaman ng produkto at transkripsyon ng talumpati) (a) Natutukoy ang paksa, layon, at ideya sa teksto (b) Nakapagtatala ng mahahalagang impormasyon (c) Naipaliliwanag ang mahahalagang ideya at detalye gamit ang diksyon, estilo, transisyonal at kohesiyong gramatikal at kaangkupan ng salita at ideya na nais iparating sa mambabasa',
  source_page = 123,
  verification_status = 'verified',
  updated_at = timezone('utc', now())
from public.curriculum_subjects cs
join public.curriculum_versions cv on cv.id = cs.curriculum_version_id
join public.curriculum_domains cd on cd.subject_id = cs.id and cd.code = 'D01'
join public.academic_periods ap on ap.subject_id = cs.id and ap.sequence = 1
join public.source_documents sd on sd.source_url = 'https://depedph-my.sharepoint.com/personal/ouct_deped_gov_ph/_layouts/15/onedrive.aspx?id=%2Fpersonal%2Fouct_deped_gov_ph%2FDocuments%2FMATATAG%20Curriculum%20Guides%2FFINAL%20MATATAG%20FILIPINO%20CG%202023%20Grades%202-10.pdf&parent=%2Fpersonal%2Fouct_deped_gov_ph%2FDocuments%2FMATATAG%20Curriculum%20Guides'
where cv.code = 'REVISED-K10-MATATAG'
  and cs.grade_level = 'Grade 7'
  and cs.name = 'Filipino'
  and cc.subject_id = cs.id
  and cc.academic_period_id = ap.id
  and cc.source_document_id = sd.id
  and cc.sort_order = 3;

