update public.curriculum_competencies cc
set domain_id = cd.id,
  competency_code = null,
  competency_text = 'Nasusuri ang mga detalye ng tekstong pampanitikan para sa kritikal na pag-unawa Mga Akda sa Panahon ng Pananakop ng Hapon • Tanaga • Haiku • Tanka (a) Natutukoy ang mahahalagang elemento (persona, sukat at tugma, talinghaga at estilo) at detalye (paksa, nilalaman at kaisipan) ng tula (b) Naipaliliwanag ang nakapaloob na pahiwatig, simbolo, talinghaga, at larawang diwa/ imahen sa tula (c) Naiuugnay ang mahahalagang kaisipan ng tula batay sa sariling pananaw, moral, katangian at karanasan ng tao (d) Nasusuri ang mahahalagang pangyayari sa teksto (tula) batay sa konteksto ng panahon, lunan at may-akda (e) Nasusuri ang mga elementong panlingguwistika (sukat, tugma, tono at talinghaga) ng tula (f) Nasusuri ang kultural na elemento (simbolo, wika, norms, pagpapahalaga at arketipo) na nakapaloob sa teksto batay sa konteksto ng panahon • Dula • Maikling kuwento (a) Natutukoy ang mahahalagang elemento (tauhan, tagpuan, banghay na tuon sa tunggalian) at detalye sa tuluyan (b) Naipaliliwanag ang banghay (gaya ng pagkakasunod-sunod ng pangyayari; pagyuyugto ng mga pangyayari (foreshadowing), pagkakahanay ng mga pangyayari (parallelism and simultaneity), pagbabalik-tanaw sa mga pangyayari (in medias res), mensahe, pahiwatig at kaisipan sa binasang tuluyan (c) Naiuugnay ang mahahalagang kaisipan ng tuluyan batay sa sariling pananaw, moral, katangian at karanasan ng tao (d) Nasusuri ang mahahalagang pangyayari ng teksto (tuluyan) batay sa konteksto ng panahon, lunan at may-akda (e) Nasusuri ang mga elementong panlingguwistika (bisa ng salita, pahiwatig, idyomatikong pahayag, estilo) ng tuluyan (f) Nasusuri ang kultural na elemento (simbolo, wika, norms, pagpapahalaga at arketipo) na nakapaloob sa teksto batay sa konteksto ng panahon',
  source_page = 140,
  verification_status = 'verified',
  updated_at = timezone('utc', now())
from public.curriculum_subjects cs
join public.curriculum_versions cv on cv.id = cs.curriculum_version_id
join public.curriculum_domains cd on cd.subject_id = cs.id and cd.code = 'D01'
join public.academic_periods ap on ap.subject_id = cs.id and ap.sequence = 3
