delete from public.curriculum_standards
where subject_id = (select cs.id from public.curriculum_subjects cs join public.curriculum_versions cv on cv.id = cs.curriculum_version_id where cv.code = 'REVISED-K10-MATATAG' and cs.grade_level = 'Grade 8' and cs.name = 'Values Education')
  and source_document_id = (select id from public.source_documents where source_url = 'https://depedph-my.sharepoint.com/personal/ouct_deped_gov_ph/_layouts/15/onedrive.aspx?id=%2Fpersonal%2Fouct_deped_gov_ph%2FDocuments%2FMATATAG%20Curriculum%20Guides%2FFINAL%20MATATAG%20GMRC%20and%20VE%20CG%202023%20Grades%201-10.pdf&parent=%2Fpersonal%2Fouct_deped_gov_ph%2FDocuments%2FMATATAG%20Curriculum%20Guides');

update public.curriculum_competencies cc
set domain_id = cd.id,
  competency_code = null,
  competency_text = 'Nakapagsasanay sa maingat na paghusga sa pamamagitan ng pagninilay sa kamalayan sa mga emosyong nararamdaman, kilos, pag-iisip, at reaksiyon ng katawan a. Naiisa-isa ang mga indikasyon ng pagkakaroon ng kamalayan sa mga emosyong nararamdaman b. Napatutunayan na ang emosyong nararamdaman ay nakatutulong upang lubos na makilala ang sarili at makatugon nang wasto sa mga nararamdaman sa bawat situwasyon tungo sa pagpapaunlad ng sarili at ugnayan sa kapuwa c. Naipakikita ang pagkilala sa mga emosyong nararamdaman',
  source_page = 213,
  verification_status = 'verified',
  updated_at = timezone('utc', now())
from public.curriculum_subjects cs
join public.curriculum_versions cv on cv.id = cs.curriculum_version_id
join public.curriculum_domains cd on cd.subject_id = cs.id and cd.code = 'D01'
join public.academic_periods ap on ap.subject_id = cs.id and ap.sequence = 1
join public.source_documents sd on sd.source_url = 'https://depedph-my.sharepoint.com/personal/ouct_deped_gov_ph/_layouts/15/onedrive.aspx?id=%2Fpersonal%2Fouct_deped_gov_ph%2FDocuments%2FMATATAG%20Curriculum%20Guides%2FFINAL%20MATATAG%20GMRC%20and%20VE%20CG%202023%20Grades%201-10.pdf&parent=%2Fpersonal%2Fouct_deped_gov_ph%2FDocuments%2FMATATAG%20Curriculum%20Guides'
where cv.code = 'REVISED-K10-MATATAG'
  and cs.grade_level = 'Grade 8'
  and cs.name = 'Values Education'
  and cc.subject_id = cs.id
  and cc.academic_period_id = ap.id
  and cc.source_document_id = sd.id
  and cc.sort_order = 1;

insert into public.curriculum_competencies (subject_id, domain_id, academic_period_id, competency_code, competency_text, sort_order, source_document_id, source_page, verification_status)
select cs.id, cd.id, ap.id, null, 'Nakapagsasanay sa maingat na paghusga sa pamamagitan ng pagninilay sa kamalayan sa mga emosyong nararamdaman, kilos, pag-iisip, at reaksiyon ng katawan a. Naiisa-isa ang mga indikasyon ng pagkakaroon ng kamalayan sa mga emosyong nararamdaman b. Napatutunayan na ang emosyong nararamdaman ay nakatutulong upang lubos na makilala ang sarili at makatugon nang wasto sa mga nararamdaman sa bawat situwasyon tungo sa pagpapaunlad ng sarili at ugnayan sa kapuwa c. Naipakikita ang pagkilala sa mga emosyong nararamdaman', 1, sd.id, 213, 'verified'
from public.curriculum_subjects cs
join public.curriculum_versions cv on cv.id = cs.curriculum_version_id
join public.curriculum_domains cd on cd.subject_id = cs.id and cd.code = 'D01'
join public.academic_periods ap on ap.subject_id = cs.id and ap.sequence = 1
join public.source_documents sd on sd.source_url = 'https://depedph-my.sharepoint.com/personal/ouct_deped_gov_ph/_layouts/15/onedrive.aspx?id=%2Fpersonal%2Fouct_deped_gov_ph%2FDocuments%2FMATATAG%20Curriculum%20Guides%2FFINAL%20MATATAG%20GMRC%20and%20VE%20CG%202023%20Grades%201-10.pdf&parent=%2Fpersonal%2Fouct_deped_gov_ph%2FDocuments%2FMATATAG%20Curriculum%20Guides'
where cv.code = 'REVISED-K10-MATATAG' and cs.grade_level = 'Grade 8' and cs.name = 'Values Education'
  and not exists (
    select 1 from public.curriculum_competencies cc
    where cc.subject_id = cs.id
      and cc.academic_period_id = ap.id
      and cc.source_document_id = sd.id
      and cc.sort_order = 1
  );

update public.curriculum_competencies cc
set domain_id = cd.id,
  competency_code = null,
  competency_text = 'Nakapagsasanay sa pagiging matatag sa pamamagitan ng mga gawaing nagpapakita ng pagpapahalaga sa mga positibong pananaw gabay ang pamilya a. Nailalarawan ang positibong pananaw gabay ang pamilya b. Naipaliliwanag na ang positibong pananaw gabay ang pamilya ay may impluwensiya sa kalusugang pangkaisipan at pangkatawan, na nagsisilbing kanlungan sa lahat ng panahon at ito ang naglilinang ng katatagan c. Naisasakilos ang mga gawain na nagpapahalaga sa mga positibong pananaw gabay ang pamilya',
  source_page = 214,
  verification_status = 'verified',
  updated_at = timezone('utc', now())
from public.curriculum_subjects cs
join public.curriculum_versions cv on cv.id = cs.curriculum_version_id
join public.curriculum_domains cd on cd.subject_id = cs.id and cd.code = 'D02'
join public.academic_periods ap on ap.subject_id = cs.id and ap.sequence = 1
join public.source_documents sd on sd.source_url = 'https://depedph-my.sharepoint.com/personal/ouct_deped_gov_ph/_layouts/15/onedrive.aspx?id=%2Fpersonal%2Fouct_deped_gov_ph%2FDocuments%2FMATATAG%20Curriculum%20Guides%2FFINAL%20MATATAG%20GMRC%20and%20VE%20CG%202023%20Grades%201-10.pdf&parent=%2Fpersonal%2Fouct_deped_gov_ph%2FDocuments%2FMATATAG%20Curriculum%20Guides'
where cv.code = 'REVISED-K10-MATATAG'
  and cs.grade_level = 'Grade 8'
  and cs.name = 'Values Education'
  and cc.subject_id = cs.id
  and cc.academic_period_id = ap.id
  and cc.source_document_id = sd.id
