update public.curriculum_competencies cc
set domain_id = cd.id,
  competency_code = null,
  competency_text = 'Nasusuri ang mga detalye ng tekstong pampanitikan para sa kritikal na pag-unawa Obra Maestra: Noli Me Tangere • Talambuhay ni Dr. Jose P. Rizal • Pagpapakilala ng mga Tauhan • Kabanata 1-18 at 21 • Kabanata 19-20, 22-46 • Kabanata 47-63 (a) Natutukoy ang mahahalagang elemento (tauhan, tagpuan, banghay na tuon sa tunggalian) at detalye sa Noli Me Tangere (b) Naipaliliwanag ang banghay (gaya ng pagkakasunod-sunod ng pangyayari; pagyuyugto ng mga pangyayari (foreshadowing), pagkakahanay ng mga pangyayari (parallelism and simultaneity), at pagbabalik-tanaw sa mga pangyayari (in medias res), mensahe, pahiwatig at kaisipan sa Noli Me Tangere (c) Naiuugnay ang mahahalagang kaisipan ng Noli Me Tangere batay sa sariling pananaw, moral, katangian at karanasan ng tao (d) Nasusuri ang mahahalagang pangyayari sa teksto (tuluyan) batay sa konteksto ng panahon, lunan, at may-akda (g) Nasusuri ang mga elementong panlingguwistika sa Noli Me Tangere (h) Nakapaghahambing ng mga tekstong hawig sa Noli Me Tangere at iba pang nobelang panlipunan ba nasusulat sa Pilipinas at sa ibang bansa',
  source_page = 158,
  verification_status = 'verified',
  updated_at = timezone('utc', now())
