  and not ((ap.sequence = 1 and cc.sort_order in (1, 2, 3, 4, 5)) or (ap.sequence = 2 and cc.sort_order in (1)) or (ap.sequence = 3 and cc.sort_order in (1, 2, 3, 4, 5, 6, 7, 8)) or (ap.sequence = 4 and cc.sort_order in (1, 2)));

