  and cc.subject_id = cs.id
  and cc.academic_period_id = ap.id
  and cc.source_document_id = sd.id
  and not ((ap.sequence = 1 and cc.sort_order in (1, 2, 3)) or (ap.sequence = 2 and cc.sort_order in (1, 2, 3, 4, 5)) or (ap.sequence = 3 and cc.sort_order in (1, 2, 3)) or (ap.sequence = 4 and cc.sort_order in (1, 2)));

-- sshs-grade-11-contemporary-literature-1.sql
insert into public.source_documents (source_type, title, issuance_code, source_url, published_on, publisher, retrieved_on, content_hash, verification_status)
values ('curriculum_guide', 'Strengthened SHS Curriculum Guide: Contemporary Literature 1', null, 'https://drive.google.com/file/d/1UyqZPgMv6YpvCurVtS9zIrJaw6zd7W6z/view', null, 'Department of Education', '2026-08-11', '79d293d6d796e8409ca11537c206bc5148ef6184cdf5dd6dc15c34187e623468', 'verified')
on conflict (source_url) where source_url is not null do update set
  title = excluded.title,
  issuance_code = excluded.issuance_code,
  published_on = excluded.published_on,
  publisher = excluded.publisher,
  retrieved_on = excluded.retrieved_on,
  content_hash = excluded.content_hash,
  verification_status = 'verified',
  updated_at = timezone('utc', now());

insert into public.curriculum_versions (code, name, framework, effective_from_school_year, effective_to_school_year, status, implementation_notes)
values ('STRENGTHENED-SHS-2026', 'Strengthened Senior High School Curriculum', 'Strengthened Senior High School Program', '2026-2027', null, 'active', 'Official source sequence is preserved as curriculum quarters/themes; school grading-period mapping remains separate.')
on conflict (code) do update set
  name = excluded.name,
  framework = excluded.framework,
  effective_from_school_year = excluded.effective_from_school_year,
  effective_to_school_year = excluded.effective_to_school_year,
  status = excluded.status,
  implementation_notes = excluded.implementation_notes,
  updated_at = timezone('utc', now());

insert into public.curriculum_applicability (curriculum_version_id, school_year, grade_level, implementation_status, priority, notes)
select cv.id, '2026-2027', 'Grade 11', 'full', 10, 'Official DepEd implementation coverage.'
from public.curriculum_versions cv where cv.code = 'STRENGTHENED-SHS-2026'
on conflict (curriculum_version_id, school_year, grade_level, implementation_status) do update set
  priority = excluded.priority,
  notes = excluded.notes;

insert into public.curriculum_subjects (curriculum_version_id, grade_level, code, name, description, source_document_id)
select cv.id, 'Grade 11', 'CONTEMPORARY-LITER11', 'Contemporary Literature 1', 'Official Grade 11 Contemporary Literature 1 competency records.', sd.id
from public.curriculum_versions cv
join public.source_documents sd on sd.source_url = 'https://drive.google.com/file/d/1UyqZPgMv6YpvCurVtS9zIrJaw6zd7W6z/view'
where cv.code = 'STRENGTHENED-SHS-2026'
on conflict (curriculum_version_id, grade_level, name) do update set
  code = excluded.code,
  description = excluded.description,
  source_document_id = excluded.source_document_id,
  updated_at = timezone('utc', now());

insert into public.academic_periods (curriculum_version_id, subject_id, label, sequence, period_type, grade_min, grade_max)
select cv.id, cs.id, 'Quarter 1', 1, 'quarter', 11, 11
from public.curriculum_versions cv
join public.curriculum_subjects cs on cs.curriculum_version_id = cv.id and cs.grade_level = 'Grade 11' and cs.name = 'Contemporary Literature 1'
where cv.code = 'STRENGTHENED-SHS-2026'
on conflict (subject_id, label) where subject_id is not null do update set
