join public.academic_periods ap on ap.subject_id = cs.id and ap.sequence = 4
join public.source_documents sd on sd.source_url = 'https://drive.google.com/file/d/1wsacnvmNEdTpZbOMWSBJfSk4mXMqMki-/view'
where cv.code = 'STRENGTHENED-SHS-2026' and cs.grade_level = 'Grade 11' and cs.name = 'Physics 2'
  and not exists (
    select 1 from public.curriculum_competencies cc
    where cc.subject_id = cs.id
      and cc.academic_period_id = ap.id
      and cc.source_document_id = sd.id
      and cc.sort_order = 8
  );

delete from public.curriculum_competencies cc
using public.curriculum_subjects cs, public.curriculum_versions cv, public.academic_periods ap, public.source_documents sd
where cs.curriculum_version_id = cv.id
  and ap.subject_id = cs.id
  and sd.source_url = 'https://drive.google.com/file/d/1wsacnvmNEdTpZbOMWSBJfSk4mXMqMki-/view'
  and cv.code = 'STRENGTHENED-SHS-2026'
  and cs.grade_level = 'Grade 11'
  and cs.name = 'Physics 2'
  and cc.subject_id = cs.id
  and cc.academic_period_id = ap.id
  and cc.source_document_id = sd.id
  and not ((ap.sequence = 3 and cc.sort_order in (1, 2, 3, 4, 5)) or (ap.sequence = 4 and cc.sort_order in (1, 2, 3, 4, 5, 6, 7, 8)));

