values ('curriculum_guide', 'Strengthened SHS Curriculum Guide: Swine Production', null, 'https://drive.google.com/file/d/1TJdtrJX1YQNYkpZDsEsY46R8w91UljHu/view', null, 'Department of Education', '2026-08-11', '10cb2ad924852efda2a3b3448603cd0caef525ed3d83031ea322e4e76c7feb87', 'verified')
on conflict (source_url) where source_url is not null do update set
  title = excluded.title,
  issuance_code = excluded.issuance_code,
  published_on = excluded.published_on,
  publisher = excluded.publisher,
  retrieved_on = excluded.retrieved_on,
  content_hash = excluded.content_hash,
  verification_status = 'verified',
  updated_at = timezone('utc', now());

