  and source_document_id = (select id from public.source_documents where source_url = 'https://drive.google.com/file/d/1ubL-HENR0fLsObKh-kHTrYQh6ZdSJhwD/view');

update public.curriculum_competencies cc
set domain_id = cd.id,
  competency_code = null,
  competency_text = 'describe the unique properties of carbon that lead to the formation of a wide variety of organic compounds;',
  source_page = 3,
  verification_status = 'verified',
  updated_at = timezone('utc', now())
from public.curriculum_subjects cs
join public.curriculum_versions cv on cv.id = cs.curriculum_version_id
join public.curriculum_domains cd on cd.subject_id = cs.id and cd.code = 'D01'
join public.academic_periods ap on ap.subject_id = cs.id and ap.sequence = 1
join public.source_documents sd on sd.source_url = 'https://drive.google.com/file/d/1ubL-HENR0fLsObKh-kHTrYQh6ZdSJhwD/view'
where cv.code = 'STRENGTHENED-SHS-2026'
  and cs.grade_level = 'Grade 12'
  and cs.name = 'Chemistry 4'
  and cc.subject_id = cs.id
  and cc.academic_period_id = ap.id
  and cc.source_document_id = sd.id
  and cc.sort_order = 1;

