insert into public.source_documents (source_type, title, issuance_code, source_url, published_on, publisher, retrieved_on, content_hash, verification_status)
values ('curriculum_guide', 'Strengthened SHS Curriculum Guide: Fundamentals of Data Analytics', null, 'https://drive.google.com/file/d/19LadJG6JAvtUP2W9iKZuh6eSa_a0gm1K/view', null, 'Department of Education', '2026-08-11', 'b11bc1ac9325a09401aebf9ba7a1492a2ed6d3e363f936df55d6c81d44cd9f89', 'verified')
on conflict (source_url) where source_url is not null do update set
  title = excluded.title,
  issuance_code = excluded.issuance_code,
